17	package org.springframework.samples.petclinic.rest.validation;
18	
19	/**
20	 * Computes the Luhn check digit over the digits contained in a string. Non-digit
21	 * characters are ignored, so a formatted code such as {@code LON-SMI-0007} is scored
22	 * over its digits alone.
23	 */
24	public final class LuhnCheckDigit {
25	
26	    private LuhnCheckDigit() {
27	    }
28	
29	    /**
30	     * Computes the single Luhn check digit for the digits found in the given value.
31	     *
32	     * @param value the string whose digits are scored (non-digits are skipped)
33	     * @return the Luhn check digit, in the range 0-9
34	     */
35	    public static int of(String value) {
36	        int sum = 0;
37	        boolean dbl = true;
38	        for (int i = value.length() - 1; i >= 0; i--) {
39	            char c = value.charAt(i);
40	            if (c < '0' || c > '9') {
41	                continue;
42	            }
43	            int d = c - '0';
44	            if (dbl) {
45	                d *= 2;
46	                if (d > 9) {
47	                    d -= 9;
48	                }
49	            }
50	            sum += d;
51	            dbl = !dbl;
52	        }
53	        return (10 - (sum % 10)) % 10;
54	    }
55	}
