17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	/**
25	 * The canonical identity of a household: an owner's last name together with the address they live
26	 * at. Two owners belong to the same household when their keys are equal. Both parts are normalized
27	 * (trimmed, internal whitespace runs collapsed to a single space, lower-cased) so values that differ
28	 * only in letter case or spacing match. This shared definition keeps household matching consistent
29	 * between the uniqueness check and the shared-identifier assignment.
30	 */
31	public final class HouseholdKey {
32	
33	    private HouseholdKey() {
34	    }
35	
36	    /**
37	     * The comparison key for the household an owner with this last name and address belongs to.
38	     */
39	    public static String of(String lastName, String address) {
40	        return normalize(lastName) + "\n" + normalize(address);
41	    }
42	
43	    /**
44	     * A stable identifier for a household key: the first 12 upper-case hex characters of its
45	     * SHA-256 digest. Deterministic, so every member of a household derives the same value.
46	     */
47	    public static String idFor(String key) {
48	        return sha256hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
49	    }
50	
51	    private static String normalize(String value) {
52	        if (value == null) {
53	            return "";
54	        }
55	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
56	    }
57	
58	    private static String sha256hex(String value) {
59	        try {
60	            byte[] digest = MessageDigest.getInstance("SHA-256")
61	                .digest(value.getBytes(StandardCharsets.UTF_8));
62	            StringBuilder sb = new StringBuilder(digest.length * 2);
63	            for (byte b : digest) {
64	                sb.append(String.format("%02x", b));
65	            }
66	            return sb.toString();
67	        }
68	        catch (NoSuchAlgorithmException ex) {
69	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
70	        }
71	    }
72	}
