16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.rest.validation.LuhnCheckDigit;
20	
21	import jakarta.persistence.*;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "membership_number")
71	    private String membershipNumber;
72	
73	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
74	    private Set<Pet> pets;
75	
76	    /**
77	     * Default the registration date to the server's current date when none was
78	     * supplied, then roll the effective date forward onto a business day so a
79	     * weekend registration date always lands on the following Monday. Runs only
80	     * on insert.
81	     */
82	    @PrePersist
83	    private void defaultRegistrationDate() {
84	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
85	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
86	    }
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    public String getTelephone() {
105	        return this.telephone;
106	    }
107	
108	    public void setTelephone(String telephone) {
109	        this.telephone = telephone;
110	    }
111	
112	    public String getEmail() {
113	        return this.email;
114	    }
115	
116	    public void setEmail(String email) {
117	        this.email = email;
118	    }
119	
120	    public String getPostcode() {
121	        return this.postcode;
122	    }
123	
124	    public void setPostcode(String postcode) {
125	        this.postcode = postcode;
126	    }
127	
128	    public LocalDate getRegistrationDate() {
129	        return this.registrationDate;
130	    }
131	
132	    public void setRegistrationDate(LocalDate registrationDate) {
133	        this.registrationDate = registrationDate;
134	    }
135	
136	    public String getCustomerCode() {
137	        return this.customerCode;
138	    }
139	
140	    public void setCustomerCode(String customerCode) {
141	        this.customerCode = customerCode;
142	    }
143	
144	    public String getHouseholdId() {
145	        return this.householdId;
146	    }
147	
148	    public void setHouseholdId(String householdId) {
149	        this.householdId = householdId;
150	    }
151	
152	    public Integer getNamesakeCount() {
153	        return this.namesakeCount;
154	    }
155	
156	    public void setNamesakeCount(Integer namesakeCount) {
157	        this.namesakeCount = namesakeCount;
158	    }
159	
160	    public String getMembershipNumber() {
161	        return this.membershipNumber;
162	    }
163	
164	    public void setMembershipNumber(String membershipNumber) {
165	        this.membershipNumber = membershipNumber;
166	    }
167	
168	    /**
169	     * Return this owner's name formatted as {@code LastName, FirstName}.
170	     */
171	    @Transient
172	    public String getDisplayName() {
173	        return this.getLastName() + ", " + this.getFirstName();
174	    }
175	
176	    /**
177	     * Return this owner's identity key: the single value all duplicate detection is based on,
178	     * formed as {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or
179	     * household id contributes an empty segment). Two owners are duplicates only when their whole
180	     * identity keys are equal, so members of the same household with different telephones — and thus
181	     * different keys — are distinct. The telephone and email are expected to already be in their
182	     * normalized storage form.
183	     */
184	    @Transient
185	    public String getIdentityKey() {
186	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
187	    }
188	
189	    private static String orEmpty(String value) {
190	        return value == null ? "" : value;
191	    }
192	
193	    /**
194	     * Return this owner's locality: the canonical region derived by looking up the
195	     * {@link #getPostcode() postcode} against the known region ranges first, falling
196	     * back to the {@link #getCity() city}-to-region table when the postcode is absent
197	     * or in no known range, or {@code UNKNOWN} when the city is not in the table either.
198	     */
199	    @Transient
200	    public String getLocality() {
201	        String region = RegionPostcodes.regionForPostcode(this.postcode);
202	        return region != null ? region : CityRegions.regionOf(this.city);
203	    }
204	
205	    /**
206	     * Return this owner's membership level: starting at 1, plus 1 when the owner
207	     * has an email, plus 1 when the owner is uniquely named (a
208	     * {@link #getNamesakeCount() namesakeCount} of 0), capped at 3. Level 4 is
209	     * reserved for tenure.
210	     */
211	    @Transient
212	    public int getMembershipLevel() {
213	        int level = 1;
214	        boolean hasEmail = this.email != null && !this.email.isEmpty();
215	        if (hasEmail) {
216	            level++;
217	        }
218	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
219	        if (uniquelyNamed) {
220	            level++;
221	        }
222	        return Math.min(level, 3);
223	    }
224	
225	    /**
226	     * Return this owner's check digit: the single Luhn check digit computed over the
227	     * digits of the {@link #getCustomerCode() customer code}.
228	     */
229	    @Transient
230	    public int getCheckDigit() {
231	        return LuhnCheckDigit.of(this.customerCode);
232	    }
233	
234	    /**
235	     * Return this owner's preferred contact channel: {@code EMAIL} when an
236	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
237	     */
238	    @Transient
239	    public String getContactPreference() {
240	        boolean hasEmail = this.email != null && !this.email.isEmpty();
241	        return hasEmail ? "EMAIL" : "PHONE";
242	    }
243	
244	    protected Set<Pet> getPetsInternal() {
245	        if (this.pets == null) {
246	            this.pets = new HashSet<>();
247	        }
248	        return this.pets;
249	    }
250	
251	    protected void setPetsInternal(Set<Pet> pets) {
252	        this.pets = pets;
253	    }
254	
255	    public List<Pet> getPets() {
256	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
257	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
258	        return Collections.unmodifiableList(sortedPets);
259	    }
260	
261	    public void setPets(List<Pet> pets) {
262	        this.pets = new HashSet<>(pets);
263	    }
264	
265	    public void addPet(Pet pet) {
266	        getPetsInternal().add(pet);
267	        pet.setOwner(this);
268	    }
269	
270	    /**
271	     * Return the Pet with the given name, or null if none found for this Owner.
272	     *
273	     * @param name to test
274	     * @return true if pet name is already in use
275	     */
276	    public Pet getPet(String name) {
277	        return getPet(name, false);
278	    }
279	
280	    /**
281	     * Return the Pet with the given name, or null if none found for this Owner.
282	     *
283	     * @param name to test
284	     * @return true if pet name is already in use
285	     */
286	    public Pet getPet(String name, boolean ignoreNew) {
287	        name = name.toLowerCase();
288	        for (Pet pet : getPetsInternal()) {
289	            if (!ignoreNew || !pet.isNew()) {
290	                String compName = pet.getName();
291	                compName = compName.toLowerCase();
292	                if (compName.equals(name)) {
293	                    return pet;
294	                }
295	            }
296	        }
297	        return null;
298	    }
299	
300	    public Pet getPet(Integer petId) {
301	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
302	    }
303	
304	    @Override
305	    public String toString() {
306	        return new ToStringCreator(this)
307	
308	            .append("id", this.getId())
309	            .append("new", this.isNew())
310	            .append("lastName", this.getLastName())
311	            .append("firstName", this.getFirstName())
312	            .append("address", this.address)
313	            .append("city", this.city)
314	            .append("telephone", this.telephone)
315	            .append("email", this.email)
316	            .toString();
317	    }
318	}
