34	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
42	import org.springframework.samples.petclinic.rest.validation.CityOwnerCapacityValidator;
43	import org.springframework.samples.petclinic.rest.validation.CityOwnerCounter;
44	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
45	import org.springframework.samples.petclinic.rest.validation.DailyRegistrationCapacityValidator;
46	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.MembershipNumberGenerator;
48	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
49	import org.springframework.samples.petclinic.rest.validation.NamesakeCounter;
50	import org.springframework.samples.petclinic.rest.validation.OwnerHouseholdRegistrar;
51	import org.springframework.samples.petclinic.rest.validation.OwnerIdentityUniquenessValidator;
52	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
53	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
54	import org.springframework.samples.petclinic.service.ClinicService;
55	import org.springframework.security.access.prepost.PreAuthorize;
56	import org.springframework.web.bind.annotation.CrossOrigin;
57	import org.springframework.web.bind.annotation.RequestMapping;
58	import org.springframework.web.bind.annotation.RestController;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final OwnerIdentityUniquenessValidator identityUniquenessValidator;
81	
82	    private final OwnerHouseholdRegistrar householdRegistrar;
83	
84	    private final NamesakeCounter namesakeCounter;
85	
86	    private final CityOwnerCounter cityOwnerCounter;
87	
88	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
89	
90	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
91	
92	    private final OwnerAuditLogger ownerAuditLogger;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper,
98	                                 OwnerIdentityUniquenessValidator identityUniquenessValidator,
99	                                 OwnerHouseholdRegistrar householdRegistrar,
100	                                 NamesakeCounter namesakeCounter,
101	                                 CityOwnerCounter cityOwnerCounter,
102	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
103	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
104	                                 OwnerAuditLogger ownerAuditLogger) {
105	        this.clinicService = clinicService;
106	        this.ownerMapper = ownerMapper;
107	        this.petMapper = petMapper;
108	        this.visitMapper = visitMapper;
109	        this.identityUniquenessValidator = identityUniquenessValidator;
110	        this.householdRegistrar = householdRegistrar;
111	        this.namesakeCounter = namesakeCounter;
112	        this.cityOwnerCounter = cityOwnerCounter;
113	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
114	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
115	        this.ownerAuditLogger = ownerAuditLogger;
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
121	        Collection<Owner> owners;
122	        if (lastName != null) {
123	            owners = this.clinicService.findOwnerByLastName(lastName);
124	        } else {
125	            owners = this.clinicService.findAllOwners();
126	        }
127	        if (owners.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
146	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
147	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
148	        HttpHeaders headers = new HttpHeaders();
149	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
150	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
151	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
152	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
153	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
154	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
155	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
156	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
157	            this.householdRegistrar.assignHousehold(owner);
158	        }
159	        this.identityUniquenessValidator.validateUnique(owner);
160	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
161	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
162	        owner.setCustomerCode(CustomerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
163	            this.cityOwnerCounter.count(owner.getCity())));
164	        this.clinicService.saveOwner(owner);
165	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
166	        this.ownerAuditLogger.logCreated(owner);
167	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
169	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
170	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        currentOwner.setAddress(ownerFieldsDto.getAddress());
181	        currentOwner.setCity(ownerFieldsDto.getCity());
182	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
183	        currentOwner.setLastName(ownerFieldsDto.getLastName());
184	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
185	        this.clinicService.saveOwner(currentOwner);
186	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Transactional
191	    @Override
192	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
193	        Owner owner = this.clinicService.findOwnerById(ownerId);
194	        if (owner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
