18	
19	/**
20	 * Derives an owner's customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
21	 * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
22	 * last name and NNNN is a per-city 4-digit, zero-padded sequence equal to one more than the
23	 * number of owners already in that city (e.g. {@code LON-SMI-0007}).
24	 */
25	public final class CustomerCodeGenerator {
26	
27	    private CustomerCodeGenerator() {
28	    }
29	
30	    /**
31	     * Builds the customer code for a new owner.
32	     *
33	     * @param city           the owner's city
34	     * @param lastName       the owner's last name
35	     * @param cityOwnerCount the number of owners already in that city
36	     * @return the customer code, e.g. {@code "LON-SMI-0007"}
37	     */
38	    public static String generate(String city, String lastName, long cityOwnerCount) {
39	        String city3 = prefix(city);
40	        String last3 = prefix(lastName);
41	        return String.format("%s-%s-%04d", city3, last3, cityOwnerCount + 1);
42	    }
43	
44	    private static String prefix(String value) {
45	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
46	    }
47	}
