16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	
20	/**
21	 * Fixed lookup of a region to its inclusive 4-digit postcode range.
22	 */
23	public final class RegionPostcodes {
24	
25	    private static final Map<String, int[]> REGION_TO_RANGE = Map.of(
26	        "NSW", new int[] {2000, 2099},
27	        "VIC", new int[] {3000, 3099},
28	        "QLD", new int[] {4000, 4099});
29	
30	    private RegionPostcodes() {
31	    }
32	
33	    /**
34	     * Return the region whose inclusive postcode range contains the given postcode, or
35	     * {@code null} when the postcode is absent, not a number, or in no known range.
36	     *
37	     * @param postcode the 4-digit postcode as text, or {@code null} if none was provided
38	     * @return the matching region, or {@code null} when no known range contains the postcode
39	     */
40	    public static String regionForPostcode(String postcode) {
41	        if (postcode == null || postcode.isBlank()) {
42	            return null;
43	        }
44	        int value;
45	        try {
46	            value = Integer.parseInt(postcode.trim());
47	        } catch (NumberFormatException ex) {
48	            return null;
49	        }
50	        for (Map.Entry<String, int[]> entry : REGION_TO_RANGE.entrySet()) {
51	            int[] range = entry.getValue();
52	            if (value >= range[0] && value <= range[1]) {
53	                return entry.getKey();
54	            }
55	        }
56	        return null;
57	    }
58	
59	    /**
60	     * Return whether the given postcode is acceptable for the given region: {@code true} when the
61	     * region has no known range (any 4-digit postcode is allowed) or the postcode falls within the
62	     * region's inclusive range.
63	     *
64	     * @param region   the canonical region (see {@link CityRegions})
65	     * @param postcode the 4-digit postcode as an integer
66	     * @return {@code true} if the postcode is acceptable for the region
67	     */
68	    public static boolean isValidForRegion(String region, int postcode) {
69	        int[] range = REGION_TO_RANGE.get(region);
70	        return range == null || (postcode >= range[0] && postcode <= range[1]);
71	    }
72	}
