26	/**
27	 * Assigns the shared household identifier when an owner opts in via {@code sharesHousehold}. When
28	 * the new owner joins an existing household (an owner with the same last name and address already
29	 * exists), every member of that household — the existing owners and the joining one — is given the
30	 * same stable {@link HouseholdKey#idFor(String) household id}. If no such household exists yet the
31	 * new owner is left without one.
32	 *
33	 * @see OwnerIdentityUniquenessValidator
34	 */
35	@Component
36	public class OwnerHouseholdRegistrar {
37	
38	    private final ClinicService clinicService;
39	
40	    public OwnerHouseholdRegistrar(ClinicService clinicService) {
41	        this.clinicService = clinicService;
42	    }
43	
44	    /**
45	     * Places the given (not-yet-saved) owner into its household, sharing a single identifier with
46	     * any existing owners at the same last name and address and backfilling that identifier onto
47	     * members that lack it.
48	     *
49	     * @param owner the owner being created with {@code sharesHousehold} set
50	     */
51	    public void assignHousehold(Owner owner) {
52	        String key = HouseholdKey.of(owner.getLastName(), owner.getAddress());
53	        List<Owner> members = this.clinicService.findAllOwners().stream()
54	            .filter(existing -> HouseholdKey.of(existing.getLastName(), existing.getAddress()).equals(key))
55	            .toList();
56	        if (members.isEmpty()) {
57	            return;
58	        }
59	        String householdId = members.stream()
60	            .map(Owner::getHouseholdId)
61	            .filter(Objects::nonNull)
62	            .findFirst()
63	            .orElseGet(() -> HouseholdKey.idFor(key));
64	        for (Owner member : members) {
65	            if (!householdId.equals(member.getHouseholdId())) {
66	                member.setHouseholdId(householdId);
67	                this.clinicService.saveOwner(member);
68	            }
69	        }
70	        owner.setHouseholdId(householdId);
71	    }
72	}
